// Verifies the HMAC-SHA256 signature Convex puts on every webhook.
// Signed message: `${timestamp}.POST.${path}.${rawBody}` (see convex/lib/hmac.ts).
const crypto = require('crypto');
const secret = $env.LENDLOOP_SHARED_SECRET;
if (!secret) throw new Error('LENDLOOP_SHARED_SECRET is not set in the n8n environment');

const PATH = '/webhook/lendloop-loan-event';
const MAX_SKEW_SECONDS = 300;
const item = $input.first();
const headers = item.json.headers || {};
const timestamp = headers['x-lendloop-timestamp'];
const signature = headers['x-lendloop-signature'];

// Use the exact bytes that were signed, not a re-serialized object.
let raw;
if (item.binary && item.binary.data) {
  raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
} else {
  raw = JSON.stringify(item.json.body);
}

const reject = (reason) => [{ json: { valid: false, reason } }];
if (!timestamp || !signature) return reject('missing signature headers');
if (Math.abs(Math.floor(Date.now() / 1000) - Number(timestamp)) > MAX_SKEW_SECONDS) return reject('timestamp outside allowed window');

const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(`${timestamp}.POST.${PATH}.${raw}`).digest('hex');
const a = Buffer.from(expected);
const b = Buffer.from(String(signature));
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) return reject('bad signature');

const event = JSON.parse(raw);

// Convex delivers at least once, so the same eventId can arrive again after a retry.
// Remember handled events (production executions persist static data) to stay idempotent.
const store = $getWorkflowStaticData('global');
store.handled = store.handled || {};
const duplicate = Boolean(store.handled[event.eventId]);

return [{ json: { valid: true, duplicate, event } }];

// Builds the message from the minimal payload Convex sends and delivers it.
// Delivery is mocked as a log line; swap this node for Email/Slack/Discord in production.
const store = $getWorkflowStaticData('global');
store.handled = store.handled || {};

// Forget events older than 7 days so static data stays small.
const WEEK = 7 * 24 * 3600 * 1000;
for (const [id, at] of Object.entries(store.handled)) if (Date.now() - at > WEEK) delete store.handled[id];

const messages = {
  'loan.requested': (e) => `${e.counterpartName} would like to borrow your ${e.loan.toolName} from ${e.loan.startDate} to ${e.loan.endDate}.`,
  'loan.approved': (e) => `Good news: ${e.counterpartName} approved your request for the ${e.loan.toolName} (${e.loan.startDate} to ${e.loan.endDate}).`,
  'loan.rejected': (e) => `Your request for the ${e.loan.toolName} (${e.loan.startDate} to ${e.loan.endDate}) was declined.`,
  'loan.cancelled': (e) => `The request for the ${e.loan.toolName} (${e.loan.startDate} to ${e.loan.endDate}) was cancelled.`,
  'loan.returned': (e) => `The ${e.loan.toolName} was marked as returned. Thanks for using LendLoop!`,
};

const out = [];
for (const item of $input.all()) {
  const { event, duplicate } = item.json;
  if (duplicate) {
    out.push({ json: { eventId: event.eventId, loanId: event.loan.id, status: 'sent', channel: 'mock-log', duplicate: true } });
    continue;
  }
  const build = messages[event.type];
  if (!build) throw new Error(`Unknown event type: ${event.type}`);
  const text = build(event);
  // Only the fields needed to notify: first name, email, message.
  console.log(`[LendLoop] notify ${event.recipient.name} <${event.recipient.email || 'no email'}>: ${text}`);
  store.handled[event.eventId] = Date.now();
  // The mock message is kept in the execution data so it can be inspected in n8n.
  out.push({ json: { eventId: event.eventId, loanId: event.loan.id, status: 'sent', channel: 'mock-log', duplicate: false, to: event.recipient.name, message: text } });
}
return out;

// Signs the write-back to Convex with the same HMAC scheme.
const crypto = require('crypto');
const secret = $env.LENDLOOP_SHARED_SECRET;
const path = '/n8n/notification-status';
const body = JSON.stringify({ eventId: $json.eventId, loanId: $json.loanId, status: $json.status, channel: $json.channel });
const timestamp = Math.floor(Date.now() / 1000).toString();
const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(`${timestamp}.POST.${path}.${body}`).digest('hex');
return { json: { duplicate: $json.duplicate, body, headers: { 'Content-Type': 'application/json', 'X-LendLoop-Timestamp': timestamp, 'X-LendLoop-Signature': signature } } };
